</input>
</sample_inputs>

Here is the source code:
<source_code>
import java.util.*;
import java.io.*;
public class littleCloves3II {
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        long n=sc.nextInt();
        long m=sc.nextInt();

        // Ensure n >= m for easier handling
        if(n < m) {
            long temp = n;
            n = m;
            m = temp;
        }

        long ans;
        if(m == 1) {
            // For 1 column, we can only place pairs with distance 3
            // Pattern repeats every 6 rows: [0,0,0,2,4,6] pairs
            long[] pattern = {0, 0, 0, 2, 4, 6};
            ans = pattern[(int)((n-1) % 6)] + 6 * ((n-1) / 6);
        } else if(m == 2) {
            if(n == 1) {
                ans = 0;
            } else if(n == 2) {
                ans = 0;
            } else if(n == 3) {
                ans = 4; // 2*2 pairs, but actually 4 chessmen = 2 pairs
            } else if(n == 4) {
                ans = 8;
            } else if(n == 5) {
                ans = 10;
            } else if(n == 6) {
                ans = 12;
            } else if(n == 7) {
                ans = 12; // based on known pattern
            } else {
                // For m=2 and n>=8, we can fill almost all cells
                ans = (n * m / 2) * 2; // even number of cells
                if((n * m) % 2 == 1) {
                    ans = (n * m - 1);
                } else {
                    ans = n * m;
                }
            }
        } else {
            // For m >= 3, we can place chessmen on all cells except possibly one
            // Maximum pairs = floor(n*m / 2), so maximum chessmen = 2 * floor(n*m / 2)
            ans = (n * m / 2) * 2;
        }

        System.out.println(ans);
    }
}
</source_code>
